GUARDS = r"""
CREATE FUNCTION protect_document() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP = 'DELETE' THEN
  RAISE EXCEPTION 'document history cannot be deleted' USING ERRCODE='55000';
 END IF;
 IF TG_OP = 'INSERT' THEN
  IF NEW.state <> 'pending' OR NEW.version <> 1 THEN
   RAISE EXCEPTION 'documents start pending' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF OLD.state = 'deleted' OR NEW.version <> OLD.version + 1
    OR (to_jsonb(NEW) - ARRAY['state','orphaned_at','storage_key','encryption_key_version',
           'nonce','stored_at','deleted_at','deletion_reason','version','updated_at',
           'updated_by_member_id']) IS DISTINCT FROM
       (to_jsonb(OLD) - ARRAY['state','orphaned_at','storage_key','encryption_key_version',
           'nonce','stored_at','deleted_at','deletion_reason','version','updated_at',
           'updated_by_member_id']) THEN
  RAISE EXCEPTION 'document metadata is immutable' USING ERRCODE='55000';
 END IF;
 IF (OLD.state = 'ready' AND NEW.state NOT IN ('ready','deleted'))
    OR (OLD.state = 'pending' AND NEW.state NOT IN ('pending','ready','deleted')) THEN
  RAISE EXCEPTION 'invalid document transition' USING ERRCODE='23514';
 END IF;
 IF OLD.storage_key IS NOT NULL AND
   ROW(NEW.storage_key,NEW.encryption_key_version,NEW.nonce,NEW.stored_at) IS DISTINCT FROM
   ROW(OLD.storage_key,OLD.encryption_key_version,OLD.nonce,OLD.stored_at) THEN
  RAISE EXCEPTION 'document content is immutable' USING ERRCODE='55000';
 END IF;
 IF OLD.state='pending' AND NEW.state='ready' AND NOT EXISTS (
   SELECT 1 FROM document_links WHERE household_id=NEW.household_id
    AND document_id=NEW.id AND active) THEN
  RAISE EXCEPTION 'uploaded document requires active target' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER protect_document BEFORE INSERT OR UPDATE OR DELETE ON documents
 FOR EACH ROW EXECUTE FUNCTION protect_document();
CREATE FUNCTION protect_document_link() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE document_state text;
BEGIN
 IF TG_OP = 'DELETE' THEN
  RAISE EXCEPTION 'document link history cannot be deleted' USING ERRCODE='55000';
 END IF;
 IF TG_OP = 'INSERT' THEN
  SELECT state INTO document_state FROM documents
   WHERE id=NEW.document_id AND household_id=NEW.household_id FOR UPDATE;
  IF NOT NEW.active OR NEW.version <> 1 OR document_state IS NULL
     OR document_state = 'deleted' THEN
   RAISE EXCEPTION 'new document link requires available document' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF NOT OLD.active OR NEW.active OR NEW.version <> OLD.version + 1
   OR (to_jsonb(NEW) - ARRAY['active','ended_at','end_reason','version','updated_at',
       'updated_by_member_id']) IS DISTINCT FROM
      (to_jsonb(OLD) - ARRAY['active','ended_at','end_reason','version','updated_at',
       'updated_by_member_id']) THEN
  RAISE EXCEPTION 'document link identity/history is immutable' USING ERRCODE='55000';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER protect_document_link BEFORE INSERT OR UPDATE OR DELETE ON document_links
 FOR EACH ROW EXECUTE FUNCTION protect_document_link();
CREATE FUNCTION document_delete_links() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF EXISTS (SELECT 1 FROM documents WHERE id=NEW.id AND state='deleted')
    AND EXISTS (SELECT 1 FROM document_links WHERE document_id=NEW.id
         AND household_id=NEW.household_id AND active) THEN
  RAISE EXCEPTION 'deleted document has active links' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER document_delete_links AFTER UPDATE ON documents
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION document_delete_links();
"""
